    await client.query(`
      INSERT INTO crop_calendar (user_id, crop_name, activity, scheduled_date, season, priority, notes, status, ai_suggestion) VALUES
      (1, 'Corn', 'Spring Planting', '2026-04-15', 'Spring', 'critical', 'Soil temp must be >10°C at 4-inch depth', 'planned', 'Optimal window: Apr 10-25. Check 10-day forecast. Treat seed with fungicide+insecticide for cold soil. Population: 34,000 seeds/acre.'),
      (1, 'Tomato', 'Transplant to Field', '2026-05-01', 'Spring', 'high', 'After last frost date. Harden off seedlings 7 days prior', 'planned', 'Wait until soil temp >15°C. Install drip irrigation before transplanting. Stake or cage at planting. Apply starter fertilizer in transplant hole.'),
      (1, 'Wheat', 'Harvest', '2026-07-10', 'Summer', 'critical', 'Monitor grain moisture - target 13-14%', 'planned', 'Test moisture daily starting July 1. Combine when grain moisture <14%. Avoid harvest losses from over-ripe shattering. Schedule truck logistics.'),
      (1, 'Potato', 'Hilling', '2026-05-20', 'Spring', 'high', 'Hill when plants are 8-10 inches tall', 'planned', 'Hill to 6 inches covering lower stems. This prevents green tubers and increases yield. Second hilling 2 weeks later if vigorous growth.'),
      (2, 'Apple', 'Dormant Spray', '2026-02-15', 'Winter', 'high', 'Apply before bud break, copper + oil', 'completed', 'Copper hydroxide at 4 lb/acre + dormant oil at 2%. Target: overwintering fungal inoculum and scale insects. Apply on calm day >4°C.'),
      (2, 'Grape', 'Pruning', '2026-03-01', 'Spring', 'critical', 'Prune to 2-bud spurs for quality wine', 'completed', 'Balance crop load: 30 buds per vine for quality. Sterilize pruning shears between blocks. Leave 1-2 extra buds as frost insurance. Paint large wounds.'),
      (2, 'Soybean', 'Planting', '2026-05-10', 'Spring', 'critical', 'Inoculate with Bradyrhizobium if first-time soybean field', 'planned', 'Row spacing 15-inch for maximum yield. Inoculant critical for new fields. Plant 140,000 seeds/acre. Check seed germination before planting.'),
      (2, 'Cotton', 'First Irrigation', '2026-06-01', 'Summer', 'high', 'Apply 2 inches when soil moisture deficit reaches 50%', 'planned', 'Install soil moisture sensors. First irrigation timing critical for root development. Avoid waterlogging. Furrow irrigation preferred for cotton.'),
      (3, 'Coffee', 'Pruning and Training', '2026-01-15', 'Winter', 'medium', 'Remove suckers, shape productive branches', 'completed', 'Maintain single-stem system. Remove all suckers below first lateral. Tip productive branches to stimulate laterals. Target 60-80 productive nodes per tree.'),
      (3, 'Banana', 'Desuckering', '2026-04-01', 'Spring', 'high', 'Keep mother + follower + peeper only', 'planned', 'Select sword suckers, not water suckers. Cut at ground level with sharp machete. Leave the most vigorous successor. Apply herbicide to unwanted sucker stumps.'),
      (3, 'Mango', 'Flower Induction', '2026-10-15', 'Fall', 'critical', 'Apply potassium nitrate spray if no natural flowering', 'planned', 'KNO3 at 2% concentration spray. Requires prior water stress period of 2-3 months. Target mature terminal shoots. Expected flowering 2-3 weeks after spray.'),
      (1, 'Strawberry', 'Runner Planting', '2026-08-15', 'Summer', 'high', 'Plant runners from certified disease-free stock', 'planned', 'Select runners with good root development. Plant crown at soil level - not too deep. Irrigate immediately. Pinch first flowers to build plant strength.'),
      (1, 'Rice', 'Transplanting', '2026-06-15', 'Summer', 'critical', '25-day old seedlings, 2-3 seedlings per hill', 'planned', 'Puddle field day before transplanting. 20x20 cm spacing for SRI method. Keep 2-3 cm water depth after transplanting. Apply basal fertilizer before puddling.'),
      (2, 'Citrus', 'Fertilizer Application', '2026-03-15', 'Spring', 'high', 'First of 3 split applications for the year', 'planned', 'Apply 1/3 annual N requirement. Spread under canopy drip line, not against trunk. Irrigate after application. Include micronutrients Zn, Mn, Fe in spring application.'),
      (3, 'Cassava', 'Planting Stakes', '2026-04-20', 'Spring', 'critical', 'Use mature stem cuttings 20-25 cm long', 'planned', 'Select stems 8-12 months old. Cut with sharp tool, not machete chop. Plant at 45-degree angle or horizontal. Spacing 1m x 1m. Apply NPK 15-15-15 at planting.')
    `);
