    // 8. Pest Alerts (15 items)
    await client.query(`
      INSERT INTO pest_alerts (user_id, alert_title, pest_name, region, severity, affected_crops, description, prevention_tips, ai_alert_analysis, is_active) VALUES
      (1, 'Fall Armyworm Migration Detected', 'Fall Armyworm', 'Midwest USA', 'critical', 'Corn, Sorghum, Rice', 'Large-scale migration from southern states confirmed by trap networks', 'Scout fields weekly, deploy pheromone traps, prepare spray equipment', 'Migration pattern consistent with warm jet stream. Expected arrival in 7-10 days. Historical damage: 20-40% yield loss. Bt corn provides partial resistance but scout for breakthrough.', true),
      (1, 'Soybean Aphid Threshold Alert', 'Soybean Aphid', 'Iowa, USA', 'high', 'Soybean', 'Aphid populations reaching economic threshold in regional monitoring', 'Scout field edges, natural enemies may provide control', 'Regional populations building to 250+ per plant threshold. Check for lady beetle and lacewing activity before spraying. Winged forms indicate migration pressure.', true),
      (2, 'Citrus Greening Quarantine Extended', 'Asian Citrus Psyllid', 'Southern California', 'critical', 'Citrus (all varieties)', 'New HLB-positive trees found, quarantine zone expanded 5 miles', 'Inspect new growth for psyllids, systemic treatment mandatory', 'Quarantine expansion significant. All citrus within zone must be treated. Report symptomatic trees immediately. No movement of citrus plant material from zone.', true),
      (2, 'Spotted Wing Drosophila Season Start', 'Spotted Wing Drosophila', 'California, USA', 'high', 'Strawberry, Blueberry, Cherry, Grape', 'First adult catches in monitoring traps, season officially started', 'Install traps, begin spray program, harvest ripe fruit promptly', 'Early season detection 10 days ahead of normal. Warm winter contributed to larger overwintering population. Spinosad + good sanitation is primary defense.', true),
      (3, 'Desert Locust Swarm Warning', 'Desert Locust', 'Western India', 'critical', 'All crops', 'Breeding swarms reported in Rajasthan, moving southeast', 'Community alert networks, prepare emergency spray teams', 'EMERGENCY ALERT: Swarm estimated at 40 million+ insects. Can consume 80,000 tonnes of food/day. Coordinate with district agriculture office. Evening spraying most effective.', true),
      (3, 'Pink Bollworm Resistance Alert', 'Pink Bollworm', 'Gujarat, India', 'high', 'Cotton', 'Field-evolved resistance to Bt cotton confirmed in multiple districts', 'Refuge planting critical, rotate Bt events, scout regularly', 'Resistance to Cry1Ac confirmed. Dual-gene Bt varieties still effective but monitor closely. Refuge compliance essential. Mating disruption as supplementary tactic.', true),
      (1, 'Corn Rootworm Beetle Emergence', 'Western Corn Rootworm', 'Corn Belt, USA', 'medium', 'Corn', 'Beetle emergence beginning across the region', 'Crop rotation, soil-applied insecticide for continuous corn', 'Rotation-resistant variant present in some areas. Sticky trap counts indicate moderate pressure. Continuous corn fields: consider soil insecticide or Bt rootworm hybrids.', true),
      (1, 'Late Blight Alert', 'Phytophthora infestans', 'Northeast USA', 'critical', 'Potato, Tomato', 'US-23 genotype confirmed in regional samples, highly aggressive', 'Begin preventive fungicide immediately, destroy cull piles', 'US-23 genotype is mefenoxam-sensitive, which is good news. But extremely aggressive. 5-7 day spray intervals required. Check DSV (disease severity values) daily.', true),
      (2, 'Navel Orangeworm Season', 'Navel Orangeworm', 'Central Valley, CA', 'high', 'Almond, Pistachio, Walnut', 'First generation flight detected, sanitation deadline approaching', 'Remove mummy nuts before April 1, deploy egg traps', 'Sanitation is THE most effective tactic. Remove 100% of mummy nuts. Mating disruption effective in well-managed orchards. Harvest timing critical for almond.', true),
      (2, 'Glassy-Winged Sharpshooter Finds', 'Glassy-Winged Sharpshooter', 'Napa Valley, CA', 'high', 'Grape', 'Vector of Pierces Disease detected in adjacent county', 'Inspect shipments, treat with systemic insecticide', 'Vector detection triggers mandatory treatment zone. Pierce Disease kills vines within 1-5 years. No cure. CDFA coordination required. Area-wide management essential.', true),
      (3, 'Tuta absoluta Spread Alert', 'Tomato Leaf Miner', 'Gujarat, India', 'high', 'Tomato', 'Invasive pest continuing rapid spread across tomato-growing regions', 'Pheromone traps, IPM approach, avoid over-reliance on insecticides', 'Resistance to multiple insecticide classes already reported globally. IPM approach essential: pheromone traps (40/ha), Trichogramma releases, spinosad rotation.', true),
      (3, 'White Grub Damage Season', 'White Grubs', 'Maharashtra, India', 'medium', 'Sugarcane, Groundnut', 'Adult beetle emergence beginning with pre-monsoon rains', 'Light traps for adult beetles, soil treatment before planting', 'June beetle flight coincides with monsoon onset. Light traps at 1/acre reduce adult population. Soil application of chlorpyrifos or Metarhizium at planting provides larval control.', true),
      (1, 'Japanese Beetle Adult Emergence', 'Japanese Beetle', 'Eastern USA', 'medium', 'Corn, Soybean, Apple, Grape', 'Adult emergence beginning, feeding damage expected for 6-8 weeks', 'Bt milky disease for grubs, hand-pick adults on small plantings', 'Adults cause cosmetic damage to many plants but rarely economic except on silk clipping in corn. Trap crops of preferred species can concentrate beetles away from cash crops.', true),
      (2, 'Brown Marmorated Stink Bug Alert', 'Brown Marmorated Stink Bug', 'Mid-Atlantic, USA', 'high', 'Apple, Peach, Tomato, Pepper, Soybean', 'Population building in border rows of orchards and vegetable fields', 'Border sprays, trap crops, samurai wasp monitoring', 'BMSB feeds on 100+ host plants. Concentrate management on field/orchard borders where bugs first colonize. Samurai wasp (Trissolcus japonicus) establishing as biocontrol.', true),
      (3, 'Banana Bunchy Top Virus Alert', 'Banana Aphid (virus vector)', 'Southern India', 'critical', 'Banana', 'BBTV detected in new districts, spread by banana aphid', 'Use virus-free planting material, control aphid vectors', 'BBTV is devastating and incurable. Eradicate infected plants immediately including corm. 10m buffer zone. Only plant tissue-culture verified clean material. Imidacloprid for aphid control.', true)
    `);
    console.log('Pest alerts seeded');

    // 9. Disease History (15 items)
    await client.query(`
      INSERT INTO disease_history (user_id, crop_name, disease_name, occurrence_date, resolution_date, treatment_used, outcome, crop_loss_percentage, lessons_learned, ai_pattern_analysis) VALUES
      (1, 'Tomato', 'Early Blight', '2025-07-15', '2025-08-10', 'Chlorothalonil + crop rotation', 'Resolved', 15.0, 'Started fungicide too late. Need preventive applications.', 'Pattern: Early blight recurs annually in July. 3-year data shows correlation with >85% humidity periods. Preventive spray at first fruit set reduces loss from 15% to <5%.'),
      (1, 'Potato', 'Late Blight', '2025-08-20', '2025-09-15', 'Metalaxyl + vine kill', 'Managed', 35.0, 'Devastating when delayed. Must respond within 24 hours.', 'Late blight is your highest-risk disease. Weather-based forecasting (DSV model) could have given 5-day warning. Consider resistant varieties for 30% of acreage as insurance.'),
      (1, 'Wheat', 'Stripe Rust', '2025-05-10', '2025-06-01', 'Propiconazole at flag leaf', 'Resolved', 8.0, 'Variety susceptibility was the issue. Switch varieties.', 'Stripe rust correlates with cool spring temperatures and southerly wind events. Variety selection is #1 defense. Flag leaf timing spray was correct. Loss would be 25%+ without treatment.'),
      (1, 'Rice', 'Sheath Blight', '2025-09-01', '2025-10-05', 'Hexaconazole + drainage management', 'Managed', 20.0, 'Dense planting worsened the disease. Reduce seeding rate.', 'Sheath blight severity directly related to plant density and nitrogen rate. Reduce seeding rate by 20%. Split nitrogen into 3 applications instead of 2.'),
      (2, 'Soybean', 'Sudden Death Syndrome', '2025-07-01', '2025-08-15', 'Fluopyram seed treatment + drainage', 'Managed', 25.0, 'Low-lying wet areas worst. Install tile drainage.', 'SDS recurs in same field areas every year - mapping hot spots allows targeted management. Fluopyram seed treatment reduces loss by 10-15%. Drainage investment has 3-year ROI.'),
      (2, 'Apple', 'Apple Scab', '2025-05-20', '2025-07-10', 'Captan + myclobutanil spray program', 'Resolved', 12.0, 'Missed critical infection period during rain events.', 'Apple scab requires rain+temperature model (Mills table) for timing sprays. 2 missed spray windows in May caused primary infection. Investment in weather station justified.'),
      (2, 'Grape', 'Botrytis Bunch Rot', '2025-09-15', '2025-10-20', 'Fenhexamid + canopy management', 'Managed', 18.0, 'Tight clusters more susceptible. Consider cluster thinning.', 'Botrytis is chronic in this vineyard. Canopy management (leaf pulling, shoot positioning) reduced incidence by 40%. Combine with bloom-time fungicide for best results.'),
      (2, 'Cotton', 'Fusarium Wilt', '2025-06-15', '2025-08-30', 'Resistant variety + soil amendment', 'Managed', 22.0, 'Soil pathogen - need long-term management strategy.', 'Fusarium persists in soil indefinitely. Transition to resistant varieties over 3 years. Soil pH management (maintain 6.5-7.0) suppresses pathogen. Biocontrol with Trichoderma shows promise.'),
      (3, 'Coffee', 'Coffee Berry Disease', '2025-11-01', '2025-12-20', 'Copper spray + selective harvesting', 'Managed', 30.0, 'Devastating loss. Need resistant variety program.', 'CBD is your most economically damaging disease. 30% loss unacceptable. Resistant varieties (Ruiru 11, Batian) reduce loss to <5%. 5-year replanting program recommended.'),
      (3, 'Banana', 'Black Sigatoka', '2025-08-10', '2025-10-15', 'Propiconazole + leaf removal', 'Managed', 15.0, 'Continuous management required - no cure.', 'Black Sigatoka requires year-round management. Oil-based sprays in dry season, systemic fungicides in wet season. 12-leaf management system keeps disease below economic threshold.'),
      (3, 'Mango', 'Powdery Mildew', '2025-02-01', '2025-03-15', 'Sulfur + wettable sulfur spray', 'Resolved', 10.0, 'Apply sulfur before flowering for prevention.', 'Powdery mildew in mango correlates with cool dry nights during flowering. Sulfur spray at panicle emergence is most cost-effective timing. Two applications usually sufficient.'),
      (1, 'Strawberry', 'Anthracnose Crown Rot', '2025-06-20', '2025-07-30', 'Azoxystrobin + plant removal', 'Managed', 40.0, 'Used contaminated transplants. Verify nursery certification.', 'Catastrophic 40% loss traced to infected transplants. ALWAYS verify nursery plant health certification. Heat-treated transplants available. Azoxystrobin dip at planting as insurance.'),
      (1, 'Corn', 'Northern Corn Leaf Blight', '2025-08-05', '2025-09-10', 'Pyraclostrobin + metconazole at VT', 'Resolved', 10.0, 'Caught early enough to protect yield.', 'NCLB appearance correlates with susceptible hybrid and 3+ hours dew period. Fungicide at VT-R1 protected 90% of yield potential. Hybrid resistance rating should be key selection criteria.'),
      (2, 'Citrus', 'Citrus Black Spot', '2025-04-10', '2025-06-30', 'Copper + strobilurin program', 'Managed', 8.0, 'Cosmetic but affects marketability.', 'Black spot primarily a cosmetic issue but causes market rejection. 4-spray program from petal fall provides adequate control. Leaf litter management reduces inoculum for next season.'),
      (3, 'Cassava', 'Cassava Brown Streak', '2025-07-25', '2025-09-30', 'Roguing + clean planting material', 'Managed', 28.0, 'Devastating root necrosis. Early harvest salvaged some roots.', 'CBSD causes internal root necrosis invisible from outside. Regular leaf symptom surveys essential. Harvest symptomatic plants early (before 9 months) to salvage usable roots.')
    `);
    console.log('Disease history seeded');

    // 10. Community Reports (15 items)
    await client.query(`
      INSERT INTO community_reports (user_id, reporter_name, report_type, title, description, location, crop_affected, severity, verified, ai_verification) VALUES
      (1, 'Tom Henderson', 'Disease Outbreak', 'Early Blight Spreading in County', 'Multiple farms reporting early blight on tomatoes, worse than last year', 'Johnson County, Iowa', 'Tomato', 'high', true, 'Verified: Early blight reports consistent with weather conditions (warm + humid). Regional advisory confirmed by extension service. Recommend preventive fungicide in adjacent counties.'),
      (1, 'Maria Garcia', 'Pest Sighting', 'Japanese Beetle Swarm Near Airport', 'Massive Japanese beetle emergence defoliating ornamentals and crops', 'Cedar Rapids, Iowa', 'Corn, Soybean, Garden Crops', 'medium', true, 'Verified: Japanese beetle emergence timing normal for region. High population this year correlates with wet spring for grub development. Economic damage primarily cosmetic except corn silk.'),
      (1, 'Bob Wilson', 'Unusual Symptoms', 'Strange Yellowing in Wheat Field', 'Wheat showing unusual yellow streaking, not matching known diseases', 'Story County, Iowa', 'Wheat', 'medium', false, 'Unverified: Symptoms could be wheat streak mosaic virus (transmitted by wheat curl mite) or herbicide drift damage. Physical sample submission to diagnostic lab recommended.'),
      (2, 'Lisa Chen', 'Disease Outbreak', 'Sudden Oak Death Found in Nursery', 'Phytophthora ramorum detected in nursery stock, quarantine imposed', 'Sonoma County, California', 'Oak, Nursery Stock', 'critical', true, 'Verified: P. ramorum is a regulated pathogen. Quarantine appropriate. All nursery stock within 1 mile should be inspected. Report to CDFA. Do not move plant material from area.'),
      (2, 'Mike Johnson', 'Pest Sighting', 'European Grapevine Moth Trap Catch', 'First trap catch of EGVM in vineyard, previously not known in area', 'Napa Valley, California', 'Grape', 'critical', true, 'Verified: EGVM (Lobesia botrana) is a quarantine pest. Regulatory response required. Mating disruption highly effective. Alert all growers within 5-mile radius.'),
      (2, 'Sarah Thompson', 'Weather Damage', 'Hail Damage Assessment - Orchard', 'Golf ball sized hail damaged 60% of apple crop, open wounds visible', 'Wenatchee, WA', 'Apple', 'critical', true, 'Verified: Post-hail bacterial infection risk high. Immediate copper spray recommended within 24 hours. Document all damage with geo-tagged photos for crop insurance claim.'),
      (3, 'Raj Kumar', 'Disease Outbreak', 'Rice Blast Epidemic in District', 'Blast disease reaching epidemic levels across multiple villages', 'Thanjavur, Tamil Nadu', 'Rice', 'critical', true, 'Verified: Magnaporthe oryzae epidemic confirmed. Correlates with unusual cool cloudy period during tillering. Emergency fungicide distribution needed. Contact district agriculture officer.'),
      (3, 'Priya Sharma', 'Pest Sighting', 'Fall Armyworm First Detection', 'Larvae found in maize field, matches fall armyworm identification guide', 'Pune, Maharashtra', 'Maize', 'high', true, 'Verified: Spodoptera frugiperda confirmed by morphological features. Invasive pest spreading rapidly. Community awareness campaign needed. Pheromone trap network should be established.'),
      (3, 'Amit Patel', 'Market Alert', 'Fungicide Shortage in Local Markets', 'Copper fungicide stocks depleted across all agricultural shops in taluka', 'Anand, Gujarat', 'All Crops', 'high', true, 'Verified: Supply chain disruption likely due to monsoon demand spike. Alternative: Bordeaux mixture can be prepared from copper sulfate + lime. Contact cooperative for bulk ordering.'),
      (1, 'James Brown', 'New Disease', 'Tar Spot First Report in County', 'Black raised lesions on corn leaves matching tar spot descriptions', 'Jasper County, Iowa', 'Corn', 'high', true, 'Verified: Phyllachora maydis (tar spot) continues northward spread. First confirmed county record. Yield impact 10-30 bu/acre in severe cases. Fungicide at VT-R1 timing recommended.'),
      (2, 'Emma Davis', 'Beneficial Sighting', 'Monarch Butterfly Migration Through Farm', 'Large numbers of monarchs observed, requesting pesticide spray delay', 'Central Valley, CA', 'Various', 'low', true, 'Verified: Monarch migration route confirmed. Delay broad-spectrum insecticide applications 5-7 days where possible. Plant milkweed buffer strips. Great opportunity for beneficial insect conservation.'),
      (2, 'David Lee', 'Pest Sighting', 'Spotted Lanternfly Egg Masses', 'Egg masses found on farm equipment arriving from Pennsylvania', 'Sacramento, CA', 'Grape, Stone Fruits', 'critical', true, 'Verified: CRITICAL biosecurity concern. Spotted lanternfly (Lycorma delicatula) not established in CA. Destroy all egg masses. Report to CDFA immediately. Quarantine equipment.'),
      (3, 'Suresh Reddy', 'Success Story', 'IPM Program Reduced Pesticide 60%', 'Village cooperative IPM program showing dramatic pesticide reduction', 'Warangal, Telangana', 'Cotton', 'low', true, 'Verified: Community IPM success story. Key components: pheromone traps, Trichogramma releases, NSKE sprays, border crops. Replicable model for neighboring villages.'),
      (1, 'Nancy White', 'Unusual Symptoms', 'Dicamba Drift Damage on Soybeans', 'Non-dicamba-tolerant soybeans showing cupping and epinasty symptoms', 'Des Moines County, Iowa', 'Soybean', 'high', true, 'Verified: Classic dicamba drift symptoms. Document with photos, note date/time, wind records. Contact state pesticide bureau. File complaint within 60 days for investigation.'),
      (3, 'Deepak Singh', 'Infrastructure', 'Cold Storage Facility Needed for District', 'Post-harvest losses reaching 30% for vegetables due to no cold storage', 'Nashik, Maharashtra', 'Vegetables', 'high', true, 'Verified: Post-harvest loss is a critical infrastructure gap. Government subsidies available under MIDH scheme. Solar-powered cold rooms suitable for remote areas. Cost: approx. ₹15-20 lakhs.')
    `);
    console.log('Community reports seeded');

    // 11. Expert Consultations (15 items)
    await client.query(`
      INSERT INTO expert_consultations (user_id, expert_name, specialization, question, crop_name, response, consultation_type, rating, status, ai_preliminary_response) VALUES
      (1, 'Dr. Sarah Mitchell', 'Plant Pathology', 'What is the best resistant tomato variety for early blight in Zone 5?', 'Tomato', 'Mountain Merit and Defiant PHR show excellent EB resistance. Both are determinate. For indeterminate, try Juliet (cherry) or Iron Lady.', 'variety_selection', 5, 'answered', 'Based on regional trial data, Mountain Merit (F1), Defiant PHR, and Iron Lady show strong Alternaria resistance. Mountain Merit also has late blight resistance.'),
      (1, 'Dr. James Rodriguez', 'Entomology', 'Are neonicotinoid seed treatments still justified for corn in my area?', 'Corn', 'Depends on your rootworm pressure and planting conditions. If soil temps >12°C at planting and you rotate crops, seed treatment ROI is negative.', 'pest_management', 4, 'answered', 'Meta-analysis shows neonicotinoid seed treatments provide inconsistent yield benefit in rotated corn. Consider using only where rootworm pressure is documented.'),
      (1, 'Dr. Emily Watson', 'Soil Science', 'My pH dropped from 6.8 to 5.9 in two years. What happened?', 'Corn', 'Likely cause: high ammonium-N fertilizer without liming. Each lb of anhydrous ammonia acidifies soil requiring 1.8 lb lime equivalent to neutralize.', 'soil_health', 5, 'answered', 'Rapid pH decline most commonly caused by nitrogen fertilizer acidification. Ammonium-based fertilizers release H+ during nitrification. Lime at 2 tons/acre, switch to UAN for less acidification.'),
      (2, 'Dr. Michael Chang', 'Pomology', 'My apple trees had a heavy crop last year and nothing this year. How do I fix biennial bearing?', 'Apple', 'Chemical thinning at petal fall is key. Use 6-BA + carbaryl at 10mm fruit size. Target 1 fruit per cluster, 6 inches between clusters.', 'crop_management', 5, 'answered', 'Biennial bearing is common in unthinned apple trees. Chemical thinning (NAA or 6-BA based) at petal fall breaks the cycle. Manual thinning as backup to achieve 40-60 leaves per fruit.'),
      (2, 'Dr. Ana Martinez', 'Viticulture', 'How do I manage smoke taint risk in my wine grapes?', 'Grape', 'Rapid harvest of affected blocks, separate vinification, activated carbon fining can reduce smoke phenols by 60%. Test free and bound volatile phenols.', 'quality_management', 4, 'answered', 'Smoke taint compounds (guaiacol, 4-methylguaiacol) bind to grape sugars. Free volatile phenols detectable by GC-MS. Activated carbon fining, early harvest, and sacrificing affected blocks may be necessary.'),
      (2, 'Dr. Robert Kim', 'Irrigation Science', 'What is the optimal deficit irrigation strategy for wine grapes?', 'Grape', 'Regulated Deficit Irrigation: irrigate at 100% ET until veraison, then reduce to 50% ET. Target midday leaf water potential of -1.2 to -1.4 MPa.', 'water_management', 5, 'answered', 'RDI for premium wine grapes: maintain adequate water pre-veraison for berry cell division. Post-veraison deficit concentrates flavors. Monitor with pressure chamber. Stem water potential more reliable than leaf.'),
      (3, 'Dr. Anita Desai', 'Tropical Agriculture', 'What is the best intercropping system for my coconut plantation?', 'Coconut', 'Coconut + cocoa is ideal for your rainfall. Below 25-year palms: cocoa gives best returns. Also consider black pepper on coconut trunks + nutmeg.', 'farm_planning', 5, 'answered', 'Multi-tier intercropping maximizes coconut plantation returns. Recommended: Coconut (top) + Cocoa (middle) + Pineapple/Ginger (ground). Adds 40-60% to plantation income with minimal competition.'),
      (3, 'Dr. Vijay Sharma', 'Plant Breeding', 'Should I switch from traditional cotton varieties to Bt cotton?', 'Cotton', 'Bt cotton provides bollworm protection but resistance management is critical. Plant 20% non-Bt refuge. Consider Bt2 (dual gene) varieties for durability.', 'variety_selection', 4, 'answered', 'Bt cotton significantly reduces bollworm damage and insecticide use. However, pink bollworm resistance to Cry1Ac is documented. Dual-gene (Cry1Ac + Cry2Ab) varieties recommended with proper refuge.'),
      (1, 'Dr. Patricia Hayes', 'Mycology', 'I found mushrooms growing in my corn field. Are they related to my disease problems?', 'Corn', 'Likely saprophytic fungi on decaying residue - not pathogenic. However, excessive residue can harbor Gibberella ear rot. Consider residue management.', 'diagnosis', 3, 'answered', 'Mushroom fruiting bodies in crop fields are usually saprophytic (decomposers) and not harmful. However, their presence indicates high organic residue. Monitor for mycotoxin-producing Fusarium in corn residue.'),
      (1, 'Dr. Thomas Grant', 'Agricultural Economics', 'Is precision agriculture worth the investment for my 500-acre farm?', 'Corn', 'At 500 acres, basic precision ag (auto-steer, yield monitor, VRA) typically pays back in 2-3 years. Start with yield mapping and VRA for lime and P.', 'farm_economics', 5, 'answered', 'Precision agriculture ROI analysis for 500-acre grain operation: GPS auto-steer saves 5-8% input overlap ($15-20/acre). Variable rate application saves $10-25/acre. Yield monitoring is foundational.'),
      (2, 'Dr. Karen Phillips', 'Food Safety', 'What are the FSMA requirements for my leafy greens operation?', 'Lettuce', 'FSMA Produce Safety Rule applies. Key: worker training, water quality testing, pre-harvest intervals for amendments, equipment sanitation, wildlife intrusion prevention.', 'compliance', 5, 'answered', 'FSMA Produce Safety Rule checklist: 1) Water quality testing (generic E. coli), 2) Biological soil amendments timing, 3) Worker hygiene training, 4) Equipment/tool sanitation, 5) Animal intrusion prevention.'),
      (2, 'Dr. David Morrison', 'Climate Science', 'How should I adapt my crop rotation for increasing drought frequency?', 'Various', 'Diversify with drought-tolerant crops (sorghum, millet). Build soil organic matter aggressively. Consider cover crop cocktails for water infiltration.', 'climate_adaptation', 4, 'answered', 'Climate adaptation strategy: 1) Soil health building increases water holding capacity (1% OM increase = 20,000 gal/acre), 2) Drought-tolerant varieties, 3) Cover crop cocktails, 4) Reduced tillage.'),
      (3, 'Dr. Lakshmi Nair', 'Organic Farming', 'How do I transition from conventional to organic banana production?', 'Banana', '3-year transition period required for certification. Start with soil building: composting, green manure cover crops. Biocontrol for Sigatoka: Trichoderma + botanical extracts.', 'organic_transition', 5, 'answered', 'Organic banana transition plan: Year 1-3 (transition): build soil biology, establish biocontrol programs, develop compost supply chain. Key challenges: Sigatoka management and nematode control without chemicals.'),
      (3, 'Dr. Rajan Menon', 'Post-Harvest', 'How can I reduce post-harvest losses in my mango export business?', 'Mango', 'Hot water treatment (52°C/5 min) for anthracnose. Modified atmosphere packaging. Cold chain maintenance at 13°C. Expect to reduce losses from 30% to under 10%.', 'post_harvest', 5, 'answered', 'Mango post-harvest protocol: 1) Harvest at mature-green stage, 2) Hot water treatment 52°C/5min, 3) Cool to 13°C within 6hrs, 4) Modified atmosphere (5% O2, 5% CO2), 5) Ethylene management.'),
      (1, 'Dr. Helen Foster', 'Weed Science', 'How do I manage herbicide-resistant waterhemp in my soybean fields?', 'Soybean', 'Waterhemp populations in Iowa commonly resist 4+ herbicide sites. Diversify: pre-emergence residuals (Authority + Dual), post with Liberty Link system, cover crops.', 'weed_management', 5, 'answered', 'Herbicide-resistant waterhemp management requires multiple effective sites of action: PRE (sulfentrazone + metolachlor) + POST (glufosinate in LL system). Cover crops reduce emergence 50-70%. Zero tolerance for seed production.')
    `);
