    // 14. Knowledge Base (15 items)
    await client.query(`
      INSERT INTO knowledge_base (title, category, content, crop_type, disease_or_pest, region, difficulty_level, tags, views, ai_enhanced_content) VALUES
      ('Understanding Early Blight in Tomatoes', 'Disease Guide', 'Early blight (Alternaria solani) is one of the most common tomato diseases worldwide. It typically starts on lower, older leaves and progresses upward.', 'Tomato', 'Early Blight', 'Global', 'beginner', 'tomato,early-blight,fungal,alternaria', 1250, 'Complete early blight management: 1) Resistant varieties (Mountain Merit, Defiant), 2) Mulching prevents soil splash, 3) Lower leaf pruning, 4) Fungicide rotation: chlorothalonil + mancozeb, 5) 3-year rotation away from Solanaceae.'),
      ('Integrated Pest Management Fundamentals', 'IPM Guide', 'IPM is a science-based approach that combines biological, cultural, physical, and chemical tools to minimize pest damage while reducing risks to people and the environment.', 'All Crops', 'General', 'Global', 'beginner', 'ipm,pest-management,biological-control,sustainable', 2340, 'IPM hierarchy: 1) Prevention (resistant varieties, clean seed, rotation), 2) Monitoring (scouting, traps, thresholds), 3) Cultural control (timing, spacing, sanitation), 4) Biological control, 5) Chemical control (last resort, targeted).'),
      ('Soil Health: The Foundation of Disease Resistance', 'Soil Science', 'Healthy soil is the first line of defense against crop diseases. Soil biodiversity suppresses pathogens, improves nutrient availability, and enhances plant immunity.', 'All Crops', 'Soil-borne Diseases', 'Global', 'intermediate', 'soil-health,disease-suppression,organic-matter,microbiome', 1890, 'Soil disease suppression mechanisms: 1) Competition for resources, 2) Antibiosis (natural antibiotics), 3) Induced systemic resistance in plants. Build suppressive soils: add diverse organic matter, minimize tillage, diverse rotations.'),
      ('Fall Armyworm: A Global Threat', 'Pest Guide', 'Spodoptera frugiperda has spread from the Americas to Africa and Asia, threatening food security for millions of smallholder farmers.', 'Corn, Rice, Sorghum', 'Fall Armyworm', 'Global', 'intermediate', 'fall-armyworm,invasive,corn,spodoptera', 3100, 'FAW management for smallholders: 1) Early detection (scout whorl stage weekly), 2) Push-pull technology (Napier border, Desmodium intercrop), 3) Bt spray for organic, 4) Selective insecticides at threshold, 5) Natural enemies: Trichogramma, earwigs, ants.'),
      ('Precision Agriculture for Smallholder Farms', 'Technology', 'Precision agriculture is not just for large farms. Smartphone-based tools are making precision techniques accessible to smallholders worldwide.', 'All Crops', 'General', 'Developing Regions', 'beginner', 'precision-ag,smartphone,technology,smallholder', 1670, 'Smartphone precision ag tools for smallholders: 1) Plantix app for disease ID, 2) AgroStar for advisory, 3) Weather apps with disease models, 4) Digital record keeping, 5) Market price apps. Total cost: just a smartphone.'),
      ('Biological Control: Natural Enemies of Crop Pests', 'Biological Control', 'Conservation and augmentation of natural enemies can reduce pest populations by 50-90% without synthetic pesticides.', 'All Crops', 'General', 'Global', 'intermediate', 'biological-control,natural-enemies,parasitoids,predators', 2100, 'Key biocontrol agents: 1) Trichogramma wasps (egg parasitoids), 2) Chrysoperla lacewings (aphid predators), 3) Phytoseiulus persimilis (spider mite predator), 4) Beauveria bassiana (entomopathogenic fungus), 5) Trichoderma (soil biocontrol).'),
      ('Climate Change and Emerging Plant Diseases', 'Climate Science', 'Climate change is altering the distribution and severity of plant diseases, creating new challenges for farmers worldwide.', 'All Crops', 'Various', 'Global', 'advanced', 'climate-change,emerging-diseases,adaptation,risk', 2450, 'Climate impacts on plant disease: 1) Range expansion of tropical pathogens northward, 2) Increased severity of heat-loving pathogens, 3) Changed phenology mismatching natural controls, 4) New pathogen-host interactions. Adaptation: diverse varieties, monitoring networks.'),
      ('Water Management for Disease Prevention', 'Irrigation', 'Irrigation management directly impacts disease development. Overhead irrigation promotes foliar diseases while drip irrigation minimizes leaf wetness.', 'All Crops', 'Fungal Diseases', 'Global', 'beginner', 'irrigation,water-management,leaf-wetness,disease-prevention', 1430, 'Irrigation and disease link: 1) Drip irrigation reduces foliar disease 40-60%, 2) Morning irrigation allows leaf drying, 3) Avoid overhead irrigation during humid periods, 4) Deficit irrigation can reduce Botrytis, 5) Proper drainage prevents root diseases.'),
      ('Organic Disease Management Strategies', 'Organic Farming', 'Organic farming relies on prevention, biodiversity, and approved natural products to manage crop diseases without synthetic fungicides.', 'All Crops', 'Various', 'Global', 'intermediate', 'organic,disease-management,copper,biocontrol,prevention', 1980, 'Organic disease management toolbox: 1) Resistant varieties (most important), 2) Crop rotation (minimum 3-year), 3) Copper products (limit accumulation), 4) Sulfur (powdery mildew), 5) Bacillus-based biofungicides, 6) Compost tea, 7) Sanitation.'),
      ('Understanding Pesticide Resistance', 'Resistance Management', 'Pesticide resistance is an evolutionary response where pest populations survive previously lethal doses. It threatens the sustainability of chemical control.', 'All Crops', 'General', 'Global', 'advanced', 'resistance,fungicide,insecticide,management,FRAC,IRAC', 2670, 'Resistance management strategy: 1) Rotate modes of action (FRAC/IRAC groups), 2) Tank mix different groups, 3) Use full recommended rate, 4) Integrate non-chemical tactics, 5) Monitor for efficacy decline. Never use same MOA more than 2 consecutive applications.'),
      ('Post-Harvest Disease Management', 'Post-Harvest', 'Up to 40% of crop production in developing countries is lost after harvest, largely due to diseases and improper storage conditions.', 'Fruits, Vegetables', 'Post-harvest Pathogens', 'Developing Regions', 'intermediate', 'post-harvest,storage,cold-chain,food-loss,developing', 1560, 'Reduce post-harvest disease: 1) Harvest at correct maturity, 2) Minimize physical damage, 3) Hot water treatment (crop-specific protocols), 4) Rapid cooling, 5) Proper storage temperature and humidity, 6) Modified atmosphere, 7) Biological agents (Candida oleophila).'),
      ('Mycotoxins in Grain: Detection and Prevention', 'Food Safety', 'Mycotoxins produced by Fusarium, Aspergillus, and Penicillium species contaminate 25% of world grain crops, posing serious health risks.', 'Grain Crops', 'Mycotoxin Producers', 'Global', 'advanced', 'mycotoxins,aflatoxin,fusarium,grain-safety,food-safety', 2230, 'Mycotoxin prevention chain: 1) Resistant varieties, 2) Harvest timing (avoid over-maturity), 3) Rapid drying to <14% moisture, 4) Clean storage facilities, 5) HACCP monitoring, 6) Biocontrol (Aflasafe for aflatoxin). Testing: ELISA for screening, LC-MS/MS for confirmation.'),
      ('Drone Technology in Crop Disease Detection', 'Technology', 'Multispectral and hyperspectral drone imagery can detect crop diseases 7-14 days before visible symptoms appear, enabling early intervention.', 'All Crops', 'Various', 'Global', 'advanced', 'drone,remote-sensing,NDVI,multispectral,early-detection', 3450, 'Drone disease detection: 1) NDVI for general stress, 2) Red-edge index for chlorophyll status, 3) Thermal for water stress, 4) AI-powered image classification for specific diseases. Cost: $5-15/acre/flight. ROI positive at 50+ acres. Regulatory: check FAA Part 107 requirements.'),
      ('Seed Treatment: First Line of Defense', 'Crop Protection', 'Modern seed treatments protect seeds and seedlings from soil-borne diseases, insects, and nematodes during the critical establishment phase.', 'All Crops', 'Soil-borne Pathogens', 'Global', 'beginner', 'seed-treatment,seedling-disease,pythium,rhizoctonia,establishment', 1340, 'Seed treatment categories: 1) Fungicide (metalaxyl + fludioxonil for Pythium + Rhizoctonia), 2) Insecticide (clothianidin for wireworm), 3) Nematicide (abamectin), 4) Biological (Trichoderma, Bacillus). Seed treatment ROI: typically 5-10:1 return on investment.'),
      ('Community-Based Plant Health Clinics', 'Extension', 'Plant health clinics bring diagnostic expertise directly to farming communities, enabling rapid disease identification and treatment recommendations.', 'All Crops', 'General', 'Developing Regions', 'beginner', 'plant-clinic,extension,diagnosis,community,smallholder', 890, 'Plant clinic model: 1) Weekly clinic at market/community center, 2) Trained plant doctor examines samples, 3) Diagnosis and treatment recommendation on-site, 4) Data collection for surveillance, 5) Referral to lab for difficult cases. Plantwise model active in 30+ countries.')
    `);
    console.log('Knowledge base seeded');

